package android.hardware.usb;import android.app.PendingIntent;import java.util.*;import java.util.concurrent.atomic.*;import java.util.function.Consumer;public class UsbManager {public static final String ACTION_USB_DEVICE_DETACHED="android.hardware.usb.action.USB_DEVICE_DETACHED",EXTRA_DEVICE="device";public final HashMap<String,UsbDevice> devices=new HashMap<>();public volatile boolean permission;public final AtomicInteger opens=new AtomicInteger(),requests=new AtomicInteger();public UsbDeviceConnection connection=new UsbDeviceConnection();public volatile PendingIntent pending;public Runnable openHook;public Consumer<PendingIntent> requestHook;public RuntimeException requestError,openError;public HashMap<String,UsbDevice> getDeviceList(){return devices;}public boolean hasPermission(UsbDevice d){return permission;}public UsbDeviceConnection openDevice(UsbDevice d){opens.incrementAndGet();if(openHook!=null)openHook.run();if(openError!=null)throw openError;return connection;}public void requestPermission(UsbDevice d,PendingIntent p){pending=p;requests.incrementAndGet();if(requestError!=null)throw requestError;if(requestHook!=null)requestHook.accept(p);}}
